package com.mcnex.conversation;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
public final class CircularSwipeProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private boolean contains(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(contains(g.getChildAt(i),text))return true;}return false;}
 private void swipe(MainActivity a,int direction){runOnMainSync(()->{View root=((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);int[] pos=new int[2];root.getLocationOnScreen(pos);float start=pos[0]+root.getWidth()*(direction>0?.8f:.2f),end=pos[0]+root.getWidth()*(direction>0?.2f:.8f),y=pos[1]+160;long t=SystemClock.uptimeMillis();a.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,start,y,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+80,MotionEvent.ACTION_MOVE,end,y,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+130,MotionEvent.ACTION_UP,end,y,0));});}
 public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(a::settings);Thread.sleep(500);swipe(a,1);Thread.sleep(450);runOnMainSync(()->{if(!contains(a.findViewById(android.R.id.content),"회의 기록 검색")&&!contains(a.findViewById(android.R.id.content),"대화는 이어지고"))throw new IllegalStateException("settings to archive failed");});swipe(a,-1);Thread.sleep(450);runOnMainSync(()->{if(!contains(a.findViewById(android.R.id.content),"회의록 설정"))throw new IllegalStateException("reverse wrap failed");});result.putString("report","settings → archive and archive → settings swipe passed");finish(-1,result);}catch(Throwable e){result.putString("error",e.toString());finish(0,result);}}
}
